import{_ as r,a0 as l,w as p,s as a,ao as d,I as i,x as s,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"在Linux中的使用 ss 命令檢查套接字/網絡連接 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux中的使用 ss 命令檢查套接字/網絡連接 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux中的使用 ss 命令檢查套接字/網絡連接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux中的使用 ss 命令檢查套接字/網絡連接 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141017 Linux ss Tool to Identify Sockets or Network Connections with Examples","title":"在Linux中的使用 ss 命令檢查套接字/網絡連接","tag":"201412","desc":""},"relativePath":"201412/20141017 Linux ss Tool to Identify Sockets or Network Connections with Examples.md","filePath":"[post].md"}'),g={name:"201412/20141017 Linux ss Tool to Identify Sockets or Network Connections with Examples.md"};function u(x,t,m,T,c,f){const n=l("Link");return p(),a("div",null,[t[13]||(t[13]=d(`<h1 id="在linux中的使用-ss-命令檢查套接字-網絡連接" tabindex="-1">在Linux中的使用 ss 命令檢查套接字/網絡連接 <a class="header-anchor" href="#在linux中的使用-ss-命令檢查套接字-網絡連接" aria-label="Permalink to “在Linux中的使用 ss 命令檢查套接字/網絡連接”">​</a></h1><p>ss是iproute2包的一部分（控制TCP/IP網絡和流量的工具）。iproute2的目標是替代先前用於配置網絡接口、路由表和管理ARP表的標準Unix網絡工具套裝（通常稱之為“net-tools”）。ss工具用於導出套接字統計，它可以顯示與netstat類似的信息，且可以顯示更多的TCP和狀態信息。因為它直接從內核空間獲取信息，所以會更快。ss的操作和netstat很像，所以這讓它可以很容易就可以取代。</p><h3 id="使用和常見選項" tabindex="-1">使用和常見選項 <a class="header-anchor" href="#使用和常見選項" aria-label="Permalink to “使用和常見選項”">​</a></h3><p>ss和netstat很像，默認它會顯示已經建立連接的開放的非監聽TCP套接字列表。並且你可以用下面的選項過濾輸出：</p><ul><li><strong>-n</strong> - 不要嘗試解析服務名。</li><li><strong>-r</strong> - 嘗試解析數字的地址/端口。</li><li><strong>-a</strong> - 顯示所有套接字。</li><li><strong>-l</strong> - 顯示監聽套接字。</li><li><strong>-p</strong> - 顯示使用該套接字的進程。</li><li><strong>-s</strong> - 打印統計數據</li><li><strong>-t</strong> - 只顯示TCP套接字。</li><li><strong>-u</strong> - 只顯示UDP套接字。</li><li><strong>-d</strong> - 只顯示DCCP套接字</li><li><strong>-w</strong> - 只顯示RAW套接字。</li><li><strong>-x</strong> - 只顯示Unix域套接字</li><li><strong>-f FAMILY</strong> - 顯示FAMILY套接字的類型。目前支持下面這些族：unix、inet、inet6、link、netlink。</li><li><strong>-A QUERY</strong> - 指定要列出的套接字列表，通過逗號分隔。可以識別下面的標識符：all、inet、tcp、udp、raw、unix、packet、netlink、unix_dgram、unix_stream、packet_raw、packet_dgram。</li><li><strong>-o STATUS</strong> - 列出指定狀態的套接字</li></ul><h3 id="ss-命令示例" tabindex="-1">ss 命令示例 <a class="header-anchor" href="#ss-命令示例" aria-label="Permalink to “ss 命令示例”">​</a></h3><p><strong>1.</strong> 顯示所有的的TCP端口和使用它們的進程：</p><pre><code># ss -tnap
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-tnap.jpg" alt="ss tnap"></p><p><strong>2.</strong> 你可以使用-4 標誌來顯示IPv4鏈接，-6標誌來顯示IPv6鏈接，比如：</p><pre><code># ss -tnap6
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-tnap6.jpg" alt="ss tnap6"></p><p><strong>3.</strong> 跟上面的行為一樣，你只需用u代替t就會顯示所有開放的UDP端口。</p><pre><code># ss -unap
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-unap.jpg" alt="ss unap"></p><p><strong>4.</strong> 你可以使用-s標誌來打印各種有用的統計數據：</p><pre><code># ss -s
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-stats.jpg" alt="ss stats"></p><p><strong>5.</strong> 你可以使用-o標誌來檢查所有不同狀態下的鏈接，比如顯示所有已經建立的連接。</p><pre><code># ss -tn -o state established -p
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/09/ss-est.jpg" alt="ss est"></p><hr>`,22)),i("p",null,[t[1]||(t[1]=s("via: ",-1)),o(n,{href:"http://linoxide.com/linux-command/ss-sockets-network-connection/"},{default:e(()=>[...t[0]||(t[0]=[s("http://linoxide.com/linux-command/ss-sockets-network-connection/",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=s("作者：",-1)),o(n,{href:"http://linoxide.com/author/adriand/"},{default:e(()=>[...t[2]||(t[2]=[s("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=s(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[3]||(t[3]=[s("geekpi",-1)])]),_:1}),t[7]||(t[7]=s(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=s("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[s("Linux中國",-1)])]),_:1}),t[12]||(t[12]=s(" 榮譽推出",-1))])])}const w=r(g,[["render",u]]);export{L as __pageData,w as default};
